
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS `new_020` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `new_020`;

DROP TABLE IF EXISTS sys_org;
CREATE TABLE sys_org (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',
  org_name VARCHAR(80) NOT NULL COMMENT '组织名称',
  org_code VARCHAR(40) NOT NULL COMMENT '组织编码',
  parent_id BIGINT DEFAULT 0 COMMENT '上级组织',
  sort INT DEFAULT 0 COMMENT '排序',
  org_type VARCHAR(20) COMMENT '组织类型',
  leader VARCHAR(50) COMMENT '负责人',
  phone VARCHAR(20) COMMENT '联系电话',
  status VARCHAR(10) DEFAULT '启用' COMMENT '状态',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='组织（合作社/服务队）';

DROP TABLE IF EXISTS sys_user;
CREATE TABLE sys_user (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  username VARCHAR(50) NOT NULL COMMENT '登录账号',
  password VARCHAR(120) NOT NULL COMMENT 'BCrypt 密码',
  real_name VARCHAR(50) COMMENT '姓名',
  avatar VARCHAR(200) COMMENT '头像相对路径',
  role_code VARCHAR(30) NOT NULL COMMENT '角色编码',
  org_id BIGINT COMMENT '所属组织',
  phone VARCHAR(20) COMMENT '手机号',
  email VARCHAR(80) COMMENT '邮箱',
  data_scope VARCHAR(10) DEFAULT 'SELF' COMMENT '数据范围 ALL/DEPT/SELF',
  status VARCHAR(10) DEFAULT '启用' COMMENT '启用/停用',
  login_fail INT DEFAULT 0 COMMENT '连续失败次数',
  locked_until DATETIME DEFAULT NULL COMMENT '锁定截止时间',
  deleted TINYINT DEFAULT 0 COMMENT '逻辑删除',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uk_user_name (username)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户';

DROP TABLE IF EXISTS sys_role;
CREATE TABLE sys_role (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  role_code VARCHAR(30) NOT NULL COMMENT '角色编码',
  role_name VARCHAR(50) NOT NULL COMMENT '角色名称',
  data_scope VARCHAR(10) DEFAULT 'SELF' COMMENT '默认数据范围',
  remark VARCHAR(200) COMMENT '说明',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uk_role_code (role_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='角色';

DROP TABLE IF EXISTS sys_menu;
CREATE TABLE sys_menu (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  parent_id BIGINT DEFAULT 0 COMMENT '上级菜单',
  menu_name VARCHAR(50) NOT NULL COMMENT '菜单名称',
  path VARCHAR(120) COMMENT '前端路由',
  icon VARCHAR(50) COMMENT '图标标识',
  sort INT DEFAULT 0 COMMENT '排序',
  visible TINYINT DEFAULT 1 COMMENT '是否可见',
  menu_type VARCHAR(10) DEFAULT 'MENU' COMMENT 'DIR/MENU',
  component VARCHAR(150) COMMENT '前端组件',
  perm VARCHAR(80) COMMENT '权限标识',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='菜单';

DROP TABLE IF EXISTS sys_role_menu;
CREATE TABLE sys_role_menu (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  role_code VARCHAR(30) NOT NULL,
  menu_id BIGINT NOT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_rm_role (role_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='角色菜单授权';

DROP TABLE IF EXISTS sys_message;
CREATE TABLE sys_message (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  receiver_id BIGINT NOT NULL COMMENT '接收人',
  title VARCHAR(120) NOT NULL COMMENT '标题',
  content VARCHAR(400) COMMENT '正文',
  biz_no VARCHAR(40) COMMENT '业务编号',
  biz_type VARCHAR(30) COMMENT '业务类型',
  url VARCHAR(150) COMMENT '跳转地址',
  is_read TINYINT DEFAULT 0 COMMENT '是否已读',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_msg_receiver (receiver_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='站内消息';

DROP TABLE IF EXISTS sys_log;
CREATE TABLE sys_log (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  user_id BIGINT COMMENT '操作人ID',
  username VARCHAR(50) COMMENT '操作人',
  module VARCHAR(50) COMMENT '模块',
  action VARCHAR(120) COMMENT '操作',
  method VARCHAR(200) COMMENT '请求方法',
  ip VARCHAR(50) COMMENT '来源IP',
  params VARCHAR(1000) COMMENT '请求参数',
  cost_ms BIGINT COMMENT '耗时毫秒',
  result VARCHAR(20) COMMENT '结果',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='操作日志';

DROP TABLE IF EXISTS sys_file;
CREATE TABLE sys_file (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  file_name VARCHAR(200) NOT NULL COMMENT '原始文件名',
  file_path VARCHAR(300) NOT NULL COMMENT '相对路径',
  file_size BIGINT COMMENT '字节数',
  content_type VARCHAR(100) COMMENT '类型',
  original_name VARCHAR(200) COMMENT '原始文件名',
  uploader VARCHAR(50) COMMENT '上传人姓名',
  upload_by BIGINT COMMENT '上传人',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='上传文件元数据';

DROP TABLE IF EXISTS sys_dict;
CREATE TABLE sys_dict (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  dict_type VARCHAR(50) NOT NULL COMMENT '字典类型',
  dict_label VARCHAR(50) NOT NULL COMMENT '显示值',
  dict_value VARCHAR(50) NOT NULL COMMENT '存储值',
  sort INT DEFAULT 0,
  KEY idx_dict_type (dict_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='数据字典';

-- ============ 业务表 ============

DROP TABLE IF EXISTS farm_machine;
CREATE TABLE farm_machine (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  machine_no VARCHAR(50) NOT NULL COMMENT '机具编号（业务唯一）',
  machine_name VARCHAR(60) NOT NULL COMMENT '机具名称',
  machine_type VARCHAR(30) NOT NULL COMMENT '机具类型',
  model VARCHAR(60) NOT NULL COMMENT '型号',
  power_hp DECIMAL(8,1) COMMENT '功率（马力）',
  work_width DECIMAL(6,2) COMMENT '作业宽度（米）',
  purchase_date DATE COMMENT '购置日期',
  total_hours DECIMAL(10,1) DEFAULT 0 COMMENT '累计工时',
  annual_check_date DATE COMMENT '年检日期',
  next_maintain_date DATE COMMENT '下次保养日期',
  work_types VARCHAR(120) COMMENT '可作业类型，逗号分隔',
  region VARCHAR(60) COMMENT '当前区域',
  current_status VARCHAR(20) DEFAULT '空闲' COMMENT '空闲/作业中/保养中/维修中/停用',
  cover_image VARCHAR(200) COMMENT '机具照片',
  hourly_cost DECIMAL(10,2) COMMENT '台班成本（元/小时）',
  fuel_per_mu DECIMAL(6,2) COMMENT '亩均油耗（升）',
  version INT DEFAULT 0 COMMENT '乐观锁版本号',
  deleted TINYINT DEFAULT 0 COMMENT '逻辑删除',
  create_by VARCHAR(50) COMMENT '创建人',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uk_machine_no (machine_no),
  KEY idx_machine_type (machine_type),
  KEY idx_machine_status (current_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='农机档案';

DROP TABLE IF EXISTS operator;
CREATE TABLE operator (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  operator_no VARCHAR(50) NOT NULL COMMENT '农机手编号',
  real_name VARCHAR(50) NOT NULL COMMENT '姓名',
  phone VARCHAR(20) COMMENT '联系电话',
  user_id BIGINT COMMENT '关联登录账号',
  license_no VARCHAR(50) COMMENT '驾驶证号',
  license_expire DATE COMMENT '驾驶证有效期至',
  cert_types VARCHAR(120) COMMENT '可驾机型',
  cert_expire DATE COMMENT '操作证有效期至',
  region VARCHAR(60) COMMENT '常驻区域',
  rating DECIMAL(3,2) DEFAULT 5.00 COMMENT '服务评分',
  total_hours DECIMAL(10,1) DEFAULT 0 COMMENT '累计工时',
  ontime_rate DECIMAL(5,2) DEFAULT 100.00 COMMENT '历史准时率（%）',
  avg_fuel DECIMAL(6,2) DEFAULT 0 COMMENT '历史亩均油耗（升）',
  hourly_wage DECIMAL(10,2) COMMENT '小时工资（元）',
  current_status VARCHAR(20) DEFAULT '在岗' COMMENT '在岗/请假/停用',
  avatar VARCHAR(200) COMMENT '头像',
  remark VARCHAR(200),
  deleted TINYINT DEFAULT 0,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uk_operator_no (operator_no),
  KEY idx_operator_status (current_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='农机手档案';

DROP TABLE IF EXISTS service_price;
CREATE TABLE service_price (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  service_type VARCHAR(30) NOT NULL COMMENT '作业类型',
  crop VARCHAR(30) NOT NULL COMMENT '作物',
  unit VARCHAR(10) DEFAULT '亩' COMMENT '计费单位',
  base_price DECIMAL(10,2) NOT NULL COMMENT '基础单价（元/亩）',
  free_km DECIMAL(6,2) DEFAULT 10 COMMENT '含免费里程（公里）',
  road_fee_per_km DECIMAL(6,2) DEFAULT 3.50 COMMENT '超出里程单价（元/公里）',
  urgent_rate DECIMAL(4,2) DEFAULT 1.15 COMMENT '加急系数',
  price_status VARCHAR(10) DEFAULT '启用' COMMENT '启用/停用',
  remark VARCHAR(200),
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='服务价目';

DROP TABLE IF EXISTS land;
CREATE TABLE land (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  land_no VARCHAR(50) NOT NULL COMMENT '地块编号',
  farmer_id BIGINT NOT NULL COMMENT '所属农户',
  land_name VARCHAR(60) NOT NULL COMMENT '地块名称',
  area DECIMAL(8,2) NOT NULL COMMENT '面积（亩）',
  crop VARCHAR(30) COMMENT '当季作物',
  region VARCHAR(60) COMMENT '所属区域',
  address VARCHAR(150) COMMENT '地块位置',
  distance_km DECIMAL(6,2) DEFAULT 0 COMMENT '距合作社里程',
  image VARCHAR(200) COMMENT '地块照片',
  remark VARCHAR(200),
  deleted TINYINT DEFAULT 0,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uk_land_no (land_no),
  KEY idx_land_farmer (farmer_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='农户地块';

DROP TABLE IF EXISTS service_request;
CREATE TABLE service_request (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  request_no VARCHAR(40) NOT NULL COMMENT '需求编号',
  farmer_id BIGINT NOT NULL COMMENT '农户',
  farmer_name VARCHAR(50) COMMENT '农户姓名（冗余便于列表展示）',
  land_id BIGINT NOT NULL COMMENT '地块',
  land_name VARCHAR(60) COMMENT '地块名称（冗余）',
  service_type VARCHAR(30) NOT NULL COMMENT '服务类型',
  crop VARCHAR(30) COMMENT '作物',
  area DECIMAL(8,2) NOT NULL COMMENT '需求面积（亩）',
  hope_date DATE COMMENT '希望作业日期',
  urgency VARCHAR(10) DEFAULT '普通' COMMENT '普通/加急/特急',
  require_desc VARCHAR(300) COMMENT '特殊要求',
  request_status VARCHAR(20) DEFAULT '待报价' COMMENT '待报价/待确认/待排程/待作业/作业中/待验收/已完成/已退回/已取消',
  dispatcher_id BIGINT COMMENT '负责调度员',
  back_reason VARCHAR(200) COMMENT '退回原因',
  total_amount DECIMAL(12,2) DEFAULT 0 COMMENT '确认金额',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uk_request_no (request_no),
  KEY idx_req_status (request_status),
  KEY idx_req_farmer (farmer_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='作业需求';

DROP TABLE IF EXISTS quotation;
CREATE TABLE quotation (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  quotation_no VARCHAR(40) NOT NULL COMMENT '报价单号',
  request_id BIGINT NOT NULL COMMENT '需求',
  request_no VARCHAR(40) COMMENT '需求编号（冗余）',
  unit_price DECIMAL(10,2) NOT NULL COMMENT '单价',
  area DECIMAL(8,2) NOT NULL COMMENT '计价面积',
  base_amount DECIMAL(12,2) NOT NULL COMMENT '基础作业费',
  road_fee DECIMAL(12,2) DEFAULT 0 COMMENT '路程附加费',
  urgent_fee DECIMAL(12,2) DEFAULT 0 COMMENT '加急附加费',
  extra_fee DECIMAL(12,2) DEFAULT 0 COMMENT '其他附加费',
  total_amount DECIMAL(12,2) NOT NULL COMMENT '报价合计',
  quote_status VARCHAR(20) DEFAULT '待确认' COMMENT '待确认/已确认/已作废/已过期',
  confirm_time DATETIME COMMENT '农户确认时间',
  expire_time DATETIME COMMENT '报价有效期',
  remark VARCHAR(200),
  create_by VARCHAR(50),
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uk_quotation_no (quotation_no),
  KEY idx_quote_request (request_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='报价单';

DROP TABLE IF EXISTS dispatch_order;
CREATE TABLE dispatch_order (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  order_no VARCHAR(40) NOT NULL COMMENT '派单号',
  request_id BIGINT NOT NULL COMMENT '需求',
  request_no VARCHAR(40) COMMENT '需求编号（冗余）',
  quotation_id BIGINT COMMENT '关联报价',
  machine_id BIGINT NOT NULL COMMENT '机具',
  machine_no VARCHAR(50) COMMENT '机具编号（冗余）',
  operator_id BIGINT NOT NULL COMMENT '农机手',
  operator_name VARCHAR(50) COMMENT '农机手姓名（冗余）',
  plan_start DATETIME COMMENT '计划开始',
  plan_end DATETIME COMMENT '计划结束',
  plan_area DECIMAL(8,2) COMMENT '计划面积',
  dispatch_status VARCHAR(20) DEFAULT '待作业' COMMENT '待作业/作业中/待验收/已完成/已取消/待返工',
  score_id BIGINT COMMENT '派单推荐评分记录',
  dispatcher_id BIGINT COMMENT '派单调度员',
  dispatch_time DATETIME COMMENT '派单时间',
  finish_time DATETIME COMMENT '完工时间',
  urgent_flag TINYINT DEFAULT 0 COMMENT '是否加急',
  remark VARCHAR(200),
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uk_order_no (order_no),
  KEY idx_order_status (dispatch_status),
  KEY idx_order_machine (machine_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='作业派单';

DROP TABLE IF EXISTS work_record;
CREATE TABLE work_record (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  order_id BIGINT NOT NULL COMMENT '派单',
  order_no VARCHAR(40) COMMENT '派单号（冗余）',
  operator_id BIGINT COMMENT '农机手',
  arrive_time DATETIME COMMENT '到场时间',
  start_time DATETIME COMMENT '开工时间',
  end_time DATETIME COMMENT '完工时间',
  actual_area DECIMAL(8,2) COMMENT '实际作业面积（亩）',
  fuel_liters DECIMAL(10,2) COMMENT '油耗（升）',
  work_hours DECIMAL(8,2) COMMENT '作业工时（小时）',
  before_image VARCHAR(200) COMMENT '作业前照片',
  after_image VARCHAR(200) COMMENT '作业后照片',
  exception_desc VARCHAR(300) COMMENT '异常说明',
  record_status VARCHAR(20) DEFAULT '进行中' COMMENT '进行中/已完工/作业中断',
  remark VARCHAR(200),
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_wr_order (order_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='作业执行记录';

DROP TABLE IF EXISTS acceptance;
CREATE TABLE acceptance (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  order_id BIGINT NOT NULL COMMENT '派单',
  order_no VARCHAR(40) COMMENT '派单号（冗余）',
  farmer_id BIGINT COMMENT '验收农户',
  accept_area DECIMAL(8,2) COMMENT '确认面积（亩）',
  quality_score INT COMMENT '作业质量评分（1-5）',
  rework_flag TINYINT DEFAULT 0 COMMENT '是否要求返工',
  rework_reason VARCHAR(300) COMMENT '返工原因',
  area_diff_rate DECIMAL(6,2) COMMENT '面积偏差率（%）',
  second_confirm TINYINT DEFAULT 0 COMMENT '面积超阈值二次确认',
  overdue_flag TINYINT DEFAULT 0 COMMENT '是否超时验收',
  comment VARCHAR(300) COMMENT '评价',
  accept_time DATETIME COMMENT '验收时间',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_acc_order (order_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='验收记录';

DROP TABLE IF EXISTS settlement;
CREATE TABLE settlement (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  settle_no VARCHAR(40) NOT NULL COMMENT '结算单号',
  order_id BIGINT NOT NULL COMMENT '派单',
  order_no VARCHAR(40) COMMENT '派单号（冗余）',
  farmer_id BIGINT COMMENT '农户',
  receivable DECIMAL(12,2) NOT NULL COMMENT '应收金额',
  received DECIMAL(12,2) DEFAULT 0 COMMENT '已收金额',
  adjust_amount DECIMAL(12,2) DEFAULT 0 COMMENT '人工调整金额（负数表示减免）',
  settle_status VARCHAR(20) DEFAULT '待收款' COMMENT '待收款/部分收款/已收款',
  pay_method VARCHAR(20) COMMENT '现金/微信/银行转账/挂账',
  voucher_image VARCHAR(200) COMMENT '收款凭证',
  settle_time DATETIME COMMENT '结算时间',
  finance_id BIGINT COMMENT '财务经办人',
  remark VARCHAR(200),
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uk_settle_no (settle_no),
  KEY idx_settle_status (settle_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='结算单';

DROP TABLE IF EXISTS machine_maintain;
CREATE TABLE machine_maintain (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  machine_id BIGINT NOT NULL COMMENT '机具',
  machine_no VARCHAR(50) COMMENT '机具编号（冗余）',
  maintain_type VARCHAR(20) NOT NULL COMMENT '保养/维修/年检',
  content VARCHAR(300) COMMENT '作业内容',
  cost DECIMAL(10,2) DEFAULT 0 COMMENT '费用（元）',
  start_date DATE COMMENT '开始日期',
  end_date DATE COMMENT '结束日期',
  attachment VARCHAR(200) COMMENT '维修单附件',
  handler VARCHAR(50) COMMENT '经办人',
  maintain_status VARCHAR(20) DEFAULT '进行中' COMMENT '进行中/已完成',
  remark VARCHAR(200),
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_mt_machine (machine_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='机具保养维修';

DROP TABLE IF EXISTS farm_rule;
CREATE TABLE farm_rule (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  rule_name VARCHAR(80) NOT NULL COMMENT '规则名称',
  rule_version VARCHAR(20) NOT NULL COMMENT '版本号',
  w_capability DECIMAL(5,2) NOT NULL COMMENT '能力匹配权重（%）',
  w_cert DECIMAL(5,2) NOT NULL COMMENT '资质有效期权重（%）',
  w_free DECIMAL(5,2) NOT NULL COMMENT '空闲时段权重（%）',
  w_distance DECIMAL(5,2) NOT NULL COMMENT '到场距离权重（%）',
  w_fuel DECIMAL(5,2) NOT NULL COMMENT '历史油耗权重（%）',
  w_ontime DECIMAL(5,2) NOT NULL COMMENT '准时率权重（%）',
  level_high DECIMAL(5,2) DEFAULT 80 COMMENT '推荐阈值',
  level_mid DECIMAL(5,2) DEFAULT 60 COMMENT '可选阈值',
  rule_status VARCHAR(10) DEFAULT '启用' COMMENT '启用/停用',
  effective_time DATETIME COMMENT '生效时间',
  remark VARCHAR(200),
  create_by VARCHAR(50),
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='派单推荐规则';

DROP TABLE IF EXISTS farm_score;
CREATE TABLE farm_score (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  rule_id BIGINT NOT NULL COMMENT '规则',
  rule_version VARCHAR(20) COMMENT '规则版本快照',
  request_id BIGINT NOT NULL COMMENT '需求',
  request_no VARCHAR(40) COMMENT '需求编号',
  machine_id BIGINT NOT NULL COMMENT '机具',
  machine_no VARCHAR(50) COMMENT '机具编号',
  operator_id BIGINT COMMENT '农机手',
  operator_name VARCHAR(50) COMMENT '农机手姓名',
  capability_score DECIMAL(6,2) COMMENT '能力匹配得分',
  cert_score DECIMAL(6,2) COMMENT '资质有效期得分',
  free_score DECIMAL(6,2) COMMENT '空闲时段得分',
  distance_score DECIMAL(6,2) COMMENT '到场距离得分',
  fuel_score DECIMAL(6,2) COMMENT '历史油耗得分',
  ontime_score DECIMAL(6,2) COMMENT '准时率得分',
  total_score DECIMAL(6,2) COMMENT '加权总分',
  result_level VARCHAR(10) COMMENT '推荐结果：推荐/可选/不推荐',
  final_level VARCHAR(10) COMMENT '人工调整后等级',
  explain_text VARCHAR(500) COMMENT '主要影响因素',
  unmet_text VARCHAR(400) COMMENT '未满足条件',
  improve_text VARCHAR(400) COMMENT '可改进项',
  snapshot JSON COMMENT '输入快照',
  adjust_reason VARCHAR(200) COMMENT '人工调整原因',
  adjust_by VARCHAR(50) COMMENT '调整人',
  adjust_time DATETIME COMMENT '调整时间',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_score_request (request_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='派单推荐计算留痕';

DROP TABLE IF EXISTS farm_record;
CREATE TABLE farm_record (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  biz_type VARCHAR(30) NOT NULL COMMENT '业务类型 REQUEST/ORDER/SETTLE',
  biz_id BIGINT NOT NULL COMMENT '业务主键',
  biz_no VARCHAR(40) COMMENT '业务编号',
  action VARCHAR(40) NOT NULL COMMENT '动作',
  from_status VARCHAR(20) COMMENT '原状态',
  to_status VARCHAR(20) COMMENT '新状态',
  operator_name VARCHAR(50) COMMENT '操作人',
  reason VARCHAR(200) COMMENT '原因/备注',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_fr_biz (biz_type, biz_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='业务时间轴';

DROP TABLE IF EXISTS farm_attachment;
CREATE TABLE farm_attachment (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  biz_type VARCHAR(30) NOT NULL COMMENT 'REQUEST/WORK/MAINTAIN/SETTLE',
  biz_id BIGINT NOT NULL,
  file_name VARCHAR(200) NOT NULL,
  file_path VARCHAR(300) NOT NULL,
  file_size BIGINT,
  upload_by VARCHAR(50),
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_fa_biz (biz_type, biz_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='业务附件元数据';

SET FOREIGN_KEY_CHECKS = 1;

USE `new_020`;

